create function public.admin_reconcile_whatsapp_market_window() returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v_issues jsonb;v_balances jsonb;v_players jsonb;v_effects jsonb;
begin
 if auth.uid() is null or not coalesce(public.is_admin(),false) then raise exception 'Somente ADMs podem conferir o encerramento';end if;
 select coalesce(jsonb_agg(jsonb_build_object('kind','balance','club',c.name,'detail','Saldo oficial difere do último lançamento','expected',x.balance_after,'actual',c.balance)),'[]'::jsonb) into v_balances from public.clubs c join lateral(select balance_after from public.transactions t where t.club_id=c.id order by t.created_at desc,t.id desc limit 1) x on true where c.deleted_at is null and c.balance is distinct from x.balance_after;
 with expected as(select distinct on(e->>'id') e->>'id' as player_id,(e->'state'->>'club_id')::uuid as club_id,s.inbox_id from public.whatsapp_market_settlement_snapshots s cross join lateral jsonb_array_elements(s.snapshot->'players') e where not exists(select 1 from public.whatsapp_market_corrections c where c.inbox_id=s.inbox_id) order by e->>'id',s.captured_at desc,s.inbox_id desc)
 select coalesce(jsonb_agg(jsonb_build_object('kind','roster','inbox_id',e.inbox_id,'player',p.name,'detail','Elenco diverge da última liquidação da central; confira operação posterior','expected_club',e.club_id,'actual_club',p.club_id)),'[]'::jsonb) into v_players from expected e left join public.players p on p.id=e.player_id::uuid where p.id is null or p.club_id is distinct from e.club_id or not p.roster_active;
 select coalesce(jsonb_agg(jsonb_build_object('kind','settlement','inbox_id',r.id,'detail','Liquidação sem evidência ou contrato oficial correspondente')),'[]'::jsonb) into v_effects from public.whatsapp_market_inbox r left join public.whatsapp_market_settlement_snapshots s on s.inbox_id=r.id where r.status='settled' and (s.inbox_id is null or (s.source_type='negotiation' and not exists(select 1 from public.negotiations n where n.id=s.source_id and n.status='executed')) or (s.source_type='transfer' and not exists(select 1 from public.transfers t where t.id=s.source_id and t.status='approved')));
 v_issues:=v_balances||v_players||v_effects;
 select v_issues||coalesce(jsonb_agg(jsonb_build_object('kind','correction','inbox_id',c.inbox_id,'detail','Compensação financeira não corresponde à liquidação original')),'[]'::jsonb) into v_issues from public.whatsapp_market_corrections c join public.whatsapp_market_settlement_snapshots s on s.inbox_id=c.inbox_id where cardinality(c.compensation_ids)<>jsonb_array_length(s.snapshot->'ledger') or exists(select 1 from (select (e->>'club_id')::uuid as club_id,(e->>'amount')::bigint as amount from jsonb_array_elements(s.snapshot->'ledger') e union all select t.club_id,t.amount from public.transactions t where t.id=any(c.compensation_ids)) q group by club_id having sum(amount)<>0);
 return jsonb_build_object('success',true,'generated_at',now(),'issues',v_issues,'checked_settlements',(select count(*) from public.whatsapp_market_inbox where status='settled'),'checked_corrections',(select count(*) from public.whatsapp_market_corrections),'pending_proposals',(select count(*) from public.whatsapp_market_inbox where status not in('settled','rejected')),'pending_contracts',(select count(*) from public.negotiations where status in('open','waiting','accepted'))+(select count(*) from public.transfers where status='pending'),'latest_ledger_checks',(select count(distinct club_id) from public.transactions));
end$$;
revoke all on function public.admin_reconcile_whatsapp_market_window() from public,anon;
grant execute on function public.admin_reconcile_whatsapp_market_window() to authenticated;
